def ensure_seed():
    have = {q.concept_key for q in DlQuestion.query.all()}
    added = 0
    for i, (concept, topic, diff, qen, qes, opts, exen, exes, ref) in enumerate(BANK):
        if concept in have:
            continue
        q = DlQuestion(concept_key=concept, topic=topic, difficulty=diff, question_en=qen, question_es=qes,
                       explanation_en=exen, explanation_es=exes, source_ref=ref, sort_order=i)
        db.session.add(q)
        db.session.flush()
        for j, (ten, tes, correct) in enumerate(opts):
            db.session.add(DlQuestionOption(question_id=q.id, text_en=ten, text_es=tes, is_correct=correct, sort_order=j))
        added += 1
    if added:
        db.session.commit()
    return added
